fn map(c: char) -> char {
    let u = c as u32;
    match RUNS.binary_search_by(|r| if u < r.0 { Ordering::Greater } else if u >= r.0 + r.1 { Ordering::Less } else { Ordering::Equal }) {
        Ok(i) => char::from_u32(RUNS[i].2 + (u - RUNS[i].0)).unwrap_or(c),
        Err(_) => c,
    }
}

use std::cmp::Ordering;

pub fn fold(s: &str) -> Cow<'_, str> {
    if s.chars().all(|c| (c as u32) < 0x2E80) {
        return Cow::Borrowed(s);
    }
    Cow::Owned(s.chars().map(map).collect())
}
